  docs["access-control.devices"] = text(
    "门禁设备监控",
    "门禁系统->门禁设备监控",
    "门禁设备监控集中查看门禁控制器、读卡器和关联视频监控点位的在线、离线与预警情况。页面提供地图视图和列表视图：地图按系统或空间定位点位并查看明细，列表按空间和条件筛选后以设备卡片查看当前状态或视频画面。",
    "顶部在“地图视图/列表视图”间切换，默认地图视图。\n地图视图：顶部四张卡片统计全部门禁监测设备的总数、在线及在线率、预警、故障/离线及需处理占比；左侧用“全部/在线/离线/预警”过滤，并在“系统类型/空间类型”间切换（系统类型获取：所属系统为门禁系统、视频监控系统的数据；空间类型为项目→管廊→舱室→区段，再次点击已选空间节点可取消）；右侧“门禁设备明细”分页展示设备名称、编码、状态、分类，每页10条；左下图例按设备分类显隐点位；地图支持放大、缩小、复位、全屏，左右面板可收起。点击地图点位或明细“查看”打开设备详情。\n列表视图：顶部卡片统计设备总数、在线数、离线数、预警数；左侧按空间类型树和状态芯片筛选；右侧按设备名称、设备编码、开始时间、结束时间搜索或重置。卡片展示设备名称、编码、状态、实时指标或视频画面、上报时间。点击卡片打开设备详情。\n设备详情含“设备信息/实时数据/历史数据”。实时数据中，门禁设备展示门状态、设备状态、今日异常等指标；视频类展示画面与视频流信息。历史数据可查看记录与曲线，支持“今日/本月/本年”切换。视频类设备不展示历史数据页签。",
    "点位名称、编码、分类、所属系统、空间归属和坐标取自门禁设备台账；视频点位取自视频监控设备；在线、离线、预警取自设备连接状态与门超时、异常通行、设备故障等结果；实时指标与上报时间取自最新一次采集。顶部统计按全部门禁监测设备计算，不随左侧筛选变化。",
    "切换地图与列表时，展示由地图点位明细流转为设备卡片，或由卡片流转回地图。地图切换系统或空间、状态芯片、图例显隐时，点位和右侧明细同步为当前筛选结果并回到第1页。列表切换空间或状态时，卡片立即按新范围刷新；点击搜索后按名称、编码和上报日期过滤，重置后恢复未填写条件。打开详情后可在设备信息、实时数据、历史数据间切换；视频类设备仅保留设备信息和实时数据。",
    "地图视图：\n1、设备总数：已接入的门禁控制器、读卡器与关联视频点位数量。\n2、在线：通信正常且未预警的设备数量；在线率=在线数÷设备总数×100%。\n3、预警：门超时、异常通行或设备故障预警的设备数量。\n4、故障 / 离线：通信中断或故障设备数量；占比=该数量÷设备总数×100%。\n列表视图：\n1、设备总数、在线数、离线数、预警数分别统计全部门禁监测设备，口径与地图四类状态一致。",
    "筛选后地图点位、明细表或设备卡片同步为当前范围；打开详情后可查看档案、当前状态或视频画面，以及历史记录和曲线。",
    [
      row("视图切换", "单选", "是", "地图视图", "固定选项：地图视图、列表视图。"),
      row("设备状态", "单选", "否", "全部", "固定选项：全部、在线、离线、预警。"),
      row("系统类型 / 空间类型", "单选", "否", "系统类型", "仅地图视图。系统类型获取：所属系统为门禁系统、视频监控系统的数据。空间类型按项目→管廊→舱室→区段筛选，再次点击已选节点取消。"),
      row("设备名称 / 设备编码", "文本", "否", "空", "列表视图模糊匹配，点击搜索后生效。"),
      row("开始时间 / 结束时间", "日期", "否", "空", "按上报日期过滤。"),
      row("监测明细", "列表展示", "否", "-", "地图右侧展示序号、设备名称、设备编码、设备状态、设备分类，每页10条。"),
      row("设备卡片", "列表展示", "否", "-", "列表视图展示名称、编码、状态、指标或视频画面、上报时间。"),
      row("分类图例", "多选开关", "否", "全部显示", "点击分类切换门禁控制器、读卡器、摄像机点位的显示或隐藏。"),
      row("设备详情页签", "单选", "否", "设备信息", "设备信息、实时数据、历史数据；视频类设备无历史数据。")
    ]
  );

