  docs["manhole-cover.monitor"] = text(
    "井盖实时监测",
    "智能井盖系统->井盖实时监测",
    "井盖实时监测集中查看智能井盖与井盖网关的开合、倾角、信号及在线状态，并支持联动视频监控点位做现场复核。页面提供地图视图和列表视图：地图按系统或空间定位点位并查看明细，列表按空间和条件筛选后以设备卡片查看当前指标或视频画面。",
    "顶部在“地图视图/列表视图”间切换，默认地图视图。\n地图视图：顶部四张卡片统计全部井盖设备的总数、在线/正常及在线率、预警/报警、故障/离线及需处理占比；左侧用“全部/在线/离线/预警”过滤，并在“系统类型/空间类型”间切换（系统类型获取：所属系统为智能井盖、视频监控系统的数据；空间类型为项目→管廊→舱室→区段，再次点击已选空间节点可取消）；右侧明细分页展示设备名称、编码、状态、分类，每页10条；图例按智能井盖、井盖网关等分类显隐点位；地图支持放大、缩小、复位、全屏。点击地图点位或“查看”打开设备详情。\n列表视图：顶部卡片统计设备总数、在线数、离线数、预警数；左侧按系统类型或空间类型树和状态芯片筛选；右侧按设备名称、设备编码、开始时间、结束时间搜索或重置。系统类型选“视频监控系统”时嵌入实时视频复核面板；选“智能井盖”时以设备卡片展示名称、编码、状态、开合状态、倾角、信号强度和上报时间。点击卡片打开设备详情。\n设备详情含“设备信息/实时数据/历史数据”。实时数据中，井盖设备展示开合状态、倾角、信号强度；视频类展示画面与流信息，离线时提示视频信号中断。历史数据可按接收时间搜索，列表分页，曲线可切换“今日/本月/本年”。视频类设备不展示历史数据页签。",
    "点位名称、编码、分类（智能井盖/井盖网关）、所属系统、空间归属和坐标取自井盖监测设备；视频点位取自视频监控设备；在线、离线、预警、报警取自设备通信状态、开合、倾角和故障结果；实时指标与上报时间取自最新一次采集；历史记录与曲线取自该设备历史采集。顶部统计按全部井盖设备计算，不含视频点位，且不随左侧筛选变化。",
    "切换地图与列表时，展示由地图点位明细流转为设备卡片或视频复核面板，或由列表流转回地图。地图切换系统或空间、状态芯片、图例显隐时，点位和右侧明细同步为当前筛选结果并回到第1页。列表切换空间、系统或状态时，卡片或视频面板立即按新范围刷新；点击搜索后按名称、编码和上报日期过滤，重置后恢复未填写条件。打开详情后可在设备信息、实时数据、历史数据间切换；视频类设备仅保留设备信息和实时数据。",
    "地图视图：\n1、设备总数：已接入的智能井盖与井盖网关数量。\n2、在线 / 正常：状态为正常的设备数量；在线率=在线数÷设备总数×100%。\n3、预警 / 报警：开启、倾斜、预警或报警状态的设备数量。\n4、故障 / 离线：故障与离线设备合计数量；占比=合计数量÷设备总数×100%。\n列表视图：\n1、设备总数、在线数、离线数、预警数分别统计全部井盖设备，口径与地图四类状态一致。",
    "筛选后地图点位、明细表、设备卡片或视频复核面板同步为当前范围；打开详情后可查看档案、当前指标或视频画面，以及历史记录和曲线。",
    [
      row("视图切换", "单选", "是", "地图视图", "固定选项：地图视图、列表视图。"),
      row("设备状态", "单选", "否", "全部", "固定选项：全部、在线、离线、预警；预警含开启、倾斜、预警、报警。"),
      row("系统类型 / 空间类型", "单选", "否", "系统类型", "系统类型获取：所属系统为智能井盖、视频监控系统的数据。空间类型按项目→管廊→舱室→区段筛选，再次点击已选节点取消。"),
      row("设备名称（列表筛选）", "文本", "否", "空", "模糊匹配设备名称，点击搜索后生效。"),
      row("设备编码（列表筛选）", "文本", "否", "空", "模糊匹配设备编码，点击搜索后生效。"),
      row("开始时间 / 结束时间", "日期", "否", "空", "按上报日期过滤。"),
      row("监测明细", "列表展示", "否", "-", "地图右侧展示序号、设备名称、设备编码、设备状态、设备分类，每页10条。"),
      row("设备卡片", "列表展示", "否", "-", "列表视图展示名称、编码、状态、开合状态、倾角、信号强度、上报时间。"),
      row("实时指标", "列表展示", "否", "-", "开合状态、倾角、信号强度。"),
      row("设备详情页签", "单选", "否", "设备信息", "设备信息、实时数据、历史数据；视频类设备无历史数据。"),
      row("历史曲线维度", "单选", "否", "今日", "固定选项：今日、本月、本年。")
    ]
  );

